DO $$DECLARE def text;BEGIN SELECT pg_get_functiondef('public.biz_demo_action(text,text,jsonb)'::regprocedure) INTO def;def:=replace(def,'IF _action=''submit'' THEN row_:=','IF _action=''submit'' AND row_->>''first_submitted_at'' IS NULL THEN row_:=row_||jsonb_build_object(''time_status'',CASE WHEN now()<=(row_->>''deadline'')::timestamptz THEN ''ontime'' ELSE ''late'' END);END IF;IF _action=''submit'' THEN row_:=');EXECUTE def;END $$;